<?php require_once 'config.php'; $logo='https://i.ibb.co/8LJmm2FH/20260904-033616.png'; $handoffToken=preg_replace('/[^a-f0-9]/i','',(string)($_GET['handoff']??'')); $signature=preg_replace('/[^a-f0-9]/i','',(string)($_GET['sig']??'')); $state=$handoffToken!==''?getVplinkReturnState($handoffToken,$signature):'missing'; $handoff=$state==='valid'?validateVplinkReturn($handoffToken,$signature):null; $blocked=$handoff===null; $bypass=in_array($state,['early','blocked'],true); if($handoff)unset($_SESSION['key_handoffs'][$handoffToken]); $payload=is_array($handoff['payload']??null)?$handoff['payload']:[]; $key=(string)($payload['key']??''); $game=(string)($payload['game']??'Application'); $duration=(string)($payload['duration_value']??'5'); $devices=(string)($payload['max_devices']??'1'); $app=(string)($payload['app_name']??'HEX PROTOCOL'); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HEX PROTOCOL — Your Key</title><link rel="icon" href="<?php echo htmlspecialchars($logo,ENT_QUOTES); ?>"><link rel="stylesheet" href="public.css"></head><body><div class="site-shell"><header class="site-header"><div class="nav-wrap"><a class="brand" href="index.php"><img class="brand-logo" src="<?php echo htmlspecialchars($logo,ENT_QUOTES); ?>" alt=""><span>HEX PROTOCOL</span></a><nav class="nav-links" style="display:flex"><a href="index.php">Generate another</a></nav></div></header><main class="page-wrap"><section class="result-panel panel"><div class="panel-head"><div><h2><?php echo $blocked?'Access blocked':'Your license key'; ?></h2><p><?php echo $blocked?'Complete the secure task before opening the key page.':'Keep this key private and use it in your application.'; ?></p></div><span class="online-badge"><?php echo $blocked?'PROTECTED':'READY'; ?></span></div><div class="form-body"><?php if($blocked): ?><div class="alert alert-danger"> <?php echo $bypass?'This handoff returned too quickly and has been blacklisted.':'This link is missing, expired, or invalid.'; ?></div><a class="btn btn-primary btn-block" href="index.php" style="margin-top:16px">Generate a new key</a><?php else: ?><div class="field-grid"><div class="feature-card"><span class="muted">Game</span><h3><?php echo htmlspecialchars($game); ?></h3></div><div class="feature-card"><span class="muted">Application</span><h3><?php echo htmlspecialchars($app); ?></h3></div></div><div class="field" style="margin-top:18px"><label for="keyInput">License key</label><div class="key-box"><input class="control" id="keyInput" value="<?php echo htmlspecialchars($key,ENT_QUOTES); ?>" readonly><button class="btn btn-primary" id="copyBtn" type="button">Copy key</button></div></div><div class="field-grid"><div class="feature-card"><span class="muted">Duration</span><h3><?php echo htmlspecialchars($duration); ?> hours</h3></div><div class="feature-card"><span class="muted">Devices</span><h3><?php echo htmlspecialchars($devices); ?></h3></div></div><div class="alert alert-success">License generated successfully. Keep your key private.</div><?php endif; ?></div></section></main><footer class="footer"><span>© 2018–<?php echo date('Y'); ?> HEX PROTOCOL</span></footer></div><script>document.getElementById('copyBtn')?.addEventListener('click',()=>{const input=document.getElementById('keyInput');navigator.clipboard?.writeText(input.value).then(()=>{document.getElementById('copyBtn').textContent='Copied ✓'})})</script></body></html>
